def chunk(text, limit):
    # your code
    pass

practice.solution:
def chunk(text, limit):
    out = []
    cur = ''
    for line in text.split('\n'):
        while len(line) > limit:
            if cur != '':
                out.append(cur)
                cur = ''
            out.append(line[:limit])
            line = line[limit:]
        if cur == '':
            cur = line
        elif len(cur) + 1 + len(line) <= limit:
            cur = cur + '\n' + line
        else:
            out.append(cur)
            cur = line
    if cur != '':
        out.append(cur)
    return out

